do $do$
declare p jsonb := $pl$[{"k":"APBIO-MCQ-SV-116-v2","t":"Nucleic Acids","s":"A laboratory technician revises the design of a synthetic RNA strand by swapping the positions of an adenine nucleotide and a cytosine nucleotide. No nucleotides are added or removed, and all other positions stay the same. What is the potential effect on the information encoded by the strand?","a":"D","c":[["A","The encoded information must remain unchanged because the strand still has the same length.",false,"Length-only trap: This mistakes nucleotide number for the information encoded by nucleotide order. Rearranging bases can change the sequence without changing strand length. Fix: Compare nucleotide positions before and after the swap, not just strand length."],["B","The encoded information must remain unchanged because the strand retains the same number of each base.",false,"Base-count trap: This equates base composition with sequence. The swap preserves each base's total count but changes where those bases occur. Fix: Track the swapped bases by position rather than comparing only their totals."],["C","The encoded information must remain unchanged because the strand retains its repeating sugar-phosphate backbone.",false,"Backbone-as-information trap: This attributes the encoded message to the repeating backbone. Information depends on the variable base sequence, which changes in this rearrangement. Fix: Identify whether the rearrangement changes base order or the repeating backbone."],["D","The encoded information can change because the rearrangement changes the nucleotide sequence.",true,"RNA encodes biological information through the order of its nucleotides. Exchanging two different bases changes that order, so the revised strand can carry different information."]]},{"k":"APBIO-MCQ-SV-116-v3","t":"Nucleic Acids","s":"A student compares a short DNA segment from a mouse with one from a fruit fly. One strand of each segment is 12 nucleotides long and contains 3 adenines, 3 thymines, 3 guanines, and 3 cytosines, but the bases appear in a different order in each strand. Which statement best explains whether these segments could carry different biological instructions?","a":"D","c":[["A","They must carry the same instructions, because each strand is exactly 12 nucleotides long.",false,"Length-only trap: this equates the size of a DNA segment with its information content. Many different sequences share a length of 12 nucleotides, so equal length says nothing about the message. Fix: Compare the order of bases along each strand, not just how many nucleotides it contains."],["B","They must carry the same instructions, because each strand has three of every base.",false,"Base-count trap: this treats base composition as if it were base sequence. Knowing how many of each base a strand has does not reveal which base sits at each position. Fix: Line up both sequences and check each position for matching bases."],["C","They must carry the same instructions, because both strands are built on the same sugar-phosphate backbone.",false,"Backbone-as-information trap: this places information in the repeating backbone instead of the bases. Every DNA strand shares the same deoxyribose-phosphate pattern, so the backbone cannot distinguish one message from another. Fix: Ask which part of a nucleotide varies from position to position along a strand."],["D","They could carry different instructions, because the information in DNA depends on the sequence in which the bases occur along the strand.",true,"Nucleic acids encode information through the linear order of their nucleotides. Rearranging the same set of bases creates a different sequence, so the two strands can specify different instructions even with identical length and base composition."]]},{"k":"APBIO-MCQ-117","t":"Nucleic Acids","s":"A researcher mixes a single-stranded DNA molecule with a second single strand that is complementary and antiparallel to it, then measures the percentage of molecules that form double strands. The researcher wants to show that pairing depends on complementary base sequence, not merely on the presence of a second DNA strand with the same bases. Which additional treatment is the most appropriate control?","a":"D","c":[["A","An RNA strand complementary to the original strand, with uracil in place of thymine",false,"This confuses changing the nucleic acid type with changing complementarity. The RNA strand is still complementary, since A pairs with U, and it also alters the sugar, so it tests DNA versus RNA rather than whether sequence matching is required. Fix: Check that the control changes only the variable named in the question."],["B","The same complementary DNA strand added at twice the concentration",false,"This treats the amount of strand as the variable being tested. Doubling concentration keeps the sequence complementary, so it cannot reveal whether pairing depends on complementarity. Fix: Ask whether the control removes the factor being tested while keeping everything else the same."],["C","The original single strand alone, with no second strand added",false,"This picks a baseline that removes the whole second strand, not just its complementarity. Low pairing here cannot separate a complementarity effect from the simple presence of a strand with the same bases, which the researcher wants to rule out. Fix: Check that the control includes every component except the one property under test."],["D","A DNA strand of the same length and the same number of each base as the complementary strand, but in an order that is not complementary",true,"This control holds length, base composition and nucleic acid type constant, so sequence complementarity is the only variable changed. If pairing drops, then matching A–T and C–G hydrogen bonding along the sequence, not just the bases present, causes the double strand to form."]]},{"k":"APBIO-MCQ-SV-117-v1","t":"Nucleic Acids","s":"A team developing a DNA-based sensor attaches 24-nucleotide DNA tags to beads. Adding complementary DNA strands produces base pairing, measured as the percentage of tags bound to an added strand. The team asks whether binding requires a matching base order rather than simply an added strand containing the same quantities of A, T, C, and G. Which comparison treatment best addresses this question? Unless a change is specified, strand concentration and all other experimental conditions remain unchanged.","a":"D","c":[["A","Add complementary 24-nucleotide RNA strands containing uracil instead of thymine.",false,"Nucleic-acid-type substitution confuses a change in molecule type with a change in complementarity. Complementary RNA still permits matching base pairs, while introducing ribose and uracil, so this comparison does not isolate base order. Fix: Keep the nucleic acid type constant when testing sequence complementarity."],["B","Add the complementary DNA strands at three times their original concentration.",false,"Concentration confusion treats strand abundance as the property under investigation. Increasing concentration leaves the matching sequence intact, so any binding difference would not isolate the requirement for complementarity. Fix: Identify the tested property, then check whether the comparison actually changes it."],["C","Test the DNA-tagged beads without adding any second strands.",false,"Missing-component baseline error removes the entire added strand instead of only its matching sequence. This baseline cannot distinguish a requirement for complementarity from a requirement for any added strand with those bases. Fix: Retain the added strand while changing only its sequence matching."],["D","Add 24-nucleotide DNA strands with the same base counts as the complementary strands but a noncomplementary sequence.",true,"This comparison preserves strand length, base composition, and DNA concentration while changing sequence complementarity. Reduced binding would support the conclusion that the order permitting A–T and C–G pairing matters, not merely the quantities of bases present."]]},{"k":"APBIO-MCQ-SV-117-v2","t":"Nucleic Acids","s":"Students are investigating the assembly of pairs of synthetic RNA strands, each 20 nucleotides long. They add an antiparallel, complementary RNA partner to a starting RNA strand and count the paired molecules formed. They want to determine whether pairing requires complementary nucleotide order rather than simply a partner containing particular quantities of each base. Which control treatment best isolates nucleotide order? All conditions remain unchanged unless a choice specifies otherwise.","a":"A","c":[["A","Replace the partner with an RNA strand of equal length and identical base counts, but with a noncomplementary base order.",true,"This comparison preserves strand length, base composition, concentration, and nucleic acid type while changing sequence complementarity. Reduced pairing would support the conclusion that matching A–U and C–G base pairs along the strands, rather than base composition alone, enables pairing."],["B","Replace the partner with a complementary DNA strand containing thymine instead of uracil.",false,"The nucleic-acid-type trap changes DNA versus RNA rather than removing complementarity. The DNA partner can still form complementary base pairs with the starting RNA, and its sugar also differs. Fix: Identify whether the replacement changes base matching or instead changes nucleic acid type."],["C","Keep the complementary RNA partner but add it at three times its original concentration.",false,"The concentration trap substitutes strand amount for nucleotide order as the experimental variable. Increasing the amount leaves complementarity intact, so any pairing difference would not isolate the effect of sequence matching. Fix: Compare the partner sequences before deciding whether a treatment tests complementarity."],["D","Test the starting RNA strand without adding any partner strand.",false,"The missing-component baseline trap removes the entire partner instead of only its complementarity. This comparison cannot distinguish a requirement for matching base order from a requirement for any second strand. Fix: Keep the partner present while changing only whether its base order is complementary."]]},{"k":"APBIO-MCQ-SV-117-v3","t":"Nucleic Acids","s":"A materials laboratory uses DNA strands to fasten two thin sheets together. One sheet carries 18-nucleotide single-stranded DNA connectors; the other carries antiparallel, complementary DNA strands. Researchers measure the percentage of connectors paired with strands on the second sheet. They want to determine whether pairing requires complementary nucleotide order rather than merely the same collection of bases. Which comparison treatment best isolates this variable? Apart from the stated change, strand amounts and experimental conditions remain constant.","a":"D","c":[["A","Replace the second sheet’s strands with complementary RNA strands containing uracil instead of thymine.",false,"Nucleic acid type confusion: substituting RNA changes the sugar and replaces thymine with uracil without removing complementarity. Complementary RNA therefore does not isolate the effect of nucleotide order. Fix: Compare the replacement’s base pairing and sugar type before selecting the control."],["B","Place twice as many of the original complementary DNA strands on the second sheet.",false,"Amount-versus-sequence confusion: increasing strand number tests availability, not complementary order. The added strands still have the matching sequence, so this comparison cannot isolate whether matching is required. Fix: Identify which property changes, and confirm it is sequence complementarity rather than strand amount."],["C","Use a second sheet with no nucleic acid strands attached.",false,"Missing-component baseline trap: removing all partner strands eliminates both their presence and their complementarity. Reduced pairing would not distinguish a requirement for matching order from a requirement for any partner strand. Fix: Keep partner strands present while changing only their ability to match the connectors."],["D","Replace the second sheet’s strands with DNA strands of equal length and identical base counts, arranged in a noncomplementary sequence.",true,"This comparison preserves strand length, base composition, and DNA identity while changing sequence complementarity. A decrease in pairing would support the importance of matching A–T and C–G bases along the strands, rather than simply having those bases present."]]},{"k":"APBIO-MCQ-118","t":"Nucleic Acids","s":"One strand of a double-stranded DNA segment has the sequence 5′-ACGTTA-3′. A change replaces the second nucleotide, C, with A; all other nucleotides remain unchanged. A new DNA strand is then synthesized complementary to the altered strand. Predict the new strand’s sequence, written in the 5′→3′ direction.","a":"D","c":[["A","5′-TTCAAT-3′",false,"Parallel-strand trap: These bases complement the altered strand position by position, but the end labels incorrectly make the strands parallel. The aligned complementary strand must run 3′→5′ opposite the given strand. Fix: Label both strands’ ends before rewriting the complement in the requested direction."],["B","5′-UAACUU-3′",false,"DNA–RNA confusion: This sequence uses uracil as the complement of adenine. The new strand is DNA, which uses thymine rather than uracil. Fix: Identify whether the requested strand is DNA or RNA before choosing complementary bases."],["C","5′-TAACGT-3′",false,"Unchanged-template trap: This sequence complements the original strand rather than the altered strand. Replacing C with A changes the corresponding complementary base from G to T. Fix: Rewrite the altered strand first, then pair its bases and check strand direction."],["D","5′-TAACTT-3′",true,"The altered strand is 5′-AAGTTA-3′. A–T and C–G pairing gives 3′-TTCAAT-5′ because DNA strands are antiparallel. Reading the complementary strand from its 5′ end gives 5′-TAACTT-3′."]]},{"k":"APBIO-MCQ-SV-118-v1","t":"Nucleic Acids","s":"A researcher redesigns a double-stranded DNA identification tag to distinguish two sample batches. The strand used to build the redesigned tag originally reads 5′-TGCATGAC-3′; the researcher substitutes A for the sixth nucleotide, G, leaving every other position unchanged. Predict the sequence of a DNA strand synthesized complementary to the redesigned strand, reported in the 5′→3′ direction.","a":"C","c":[["A","5′-ACGTATTG-3′",false,"Parallel-strand trap: The base matches are appropriate, but the end labels place both aligned strands in the same direction. Opposite the redesigned strand, this complementary sequence must be labeled 3′-ACGTATTG-5′. Fix: Mark opposite ends on the aligned strands, then read the complement from 5′."],["B","5′-GUUAUGCA-3′",false,"DNA–RNA confusion: Using U opposite A applies RNA base pairing to a requested DNA strand. DNA contains thymine, not uracil. Fix: Identify the requested nucleic acid before selecting T or U."],["C","5′-GTTATGCA-3′",true,"The redesigned strand reads 5′-TGCATAAC-3′. Complementary base pairing and antiparallel orientation produce an aligned strand of 3′-ACGTATTG-5′. Reversing the order to report that strand 5′→3′ gives 5′-GTTATGCA-3′."],["D","5′-GTCATGCA-3′",false,"Unchanged-template trap: This sequence is complementary to the tag before redesign. The G-to-A substitution requires a corresponding C-to-T change in the newly synthesized complement. Fix: Write the redesigned sequence before constructing and orienting its complement."]]},{"k":"APBIO-MCQ-SV-118-v2","t":"Nucleic Acids","s":"A botanist finds that a DNA strand in one seedling reads 5′-GATCCAG-3′. In a second seedling, the corresponding strand differs only at position 2, where G replaces A. If a new DNA strand is synthesized complementary to the second seedling’s strand, what sequence will it have when read 5′→3′?","a":"D","c":[["A","5′-CCAGGTC-3′",false,"Parallel-strand trap: The bases are correctly paired in their aligned order, but the end labels incorrectly give both strands the same direction. The complementary strand’s 5′ end lies opposite the given strand’s 3′ end. Fix: Mark opposite end labels on aligned strands, then read from the new strand’s 5′ end."],["B","5′-CUGGACC-3′",false,"DNA–RNA confusion: Using U opposite A applies RNA pairing to a DNA product. A complementary DNA strand contains T opposite A, not U. Fix: Check the product’s nucleic acid type before selecting T or U."],["C","5′-CTGGATC-3′",false,"Unchanged-template trap: This sequence is the reverse complement of the first seedling’s strand, ignoring the substitution in the second. Changing A to G requires C instead of T at the paired position. Fix: Enter the substitution into the given sequence before constructing its reverse complement."],["D","5′-CTGGACC-3′",true,"After the substitution, the strand reads 5′-GGTCCAG-3′, so complementary base pairing produces an aligned strand of 3′-CCAGGTC-5′. Because the strands run antiparallel, reading the new strand from its 5′ end yields 5′-CTGGACC-3′."]]},{"k":"APBIO-MCQ-SV-118-v3","t":"Nucleic Acids","s":"An artificial DNA molecule stores information for a digital archive. During an update, a technician changes the seventh nucleotide of a strand from A to G without altering any other position. Before the update, that strand reads 5′-CTAGGCAT-3′. What sequence is predicted for a new DNA strand synthesized complementary to the updated strand, written 5′→3′?","a":"C","c":[["A","5′-GATCCGCA-3′",false,"Parallel-strand trap: The bases match the updated strand's complement in aligned order, but the labels place both strands in the same direction. Complementary DNA strands have opposite orientations. Fix: Mark the complement's ends, then read from its 5′ end."],["B","5′-ACGCCUAG-3′",false,"DNA–RNA confusion: Using U opposite A treats the requested product as RNA. A complementary DNA strand contains thymine, not uracil. Fix: Check the requested nucleic acid type before assigning partners to adenine."],["C","5′-ACGCCTAG-3′",true,"After the replacement, the strand reads 5′-CTAGGCGT-3′. Complementary base pairing produces 3′-GATCCGCA-5′, with opposite end orientations because DNA strands are antiparallel. Rewriting this complement from its 5′ end yields 5′-ACGCCTAG-3′."],["D","5′-ATGCCTAG-3′",false,"Unchanged-template trap: This sequence is the reverse complement of the strand before the update. The A-to-G replacement requires C rather than T at the corresponding position in the new strand. Fix: Apply the replacement to the given sequence before constructing its reverse complement."]]}]$pl$::jsonb; r jsonb; c jsonb; v_ci uuid; v_civ uuid; n int;
begin
  if jsonb_array_length(p) <> 10 then raise exception 'chunk size'; end if;
  if exists (select 1 from app.content_items ci where ci.exam_pack_version_id='2d88ba5e-a6a3-43b8-bfae-9e5505a178a7' and ci.content_key in (select x->>'k' from jsonb_array_elements(p) x))
    then raise exception 'chunk already loaded'; end if;
  for r in select * from jsonb_array_elements(p) loop
    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values ('2d88ba5e-a6a3-43b8-bfae-9e5505a178a7', r->>'k', 'mcq', r->>'t', 'draft') returning id into v_ci;
    insert into app.content_item_versions (content_item_id, version_num, stem, stimulus, content_hash, status, review_status, canonical_answer_1)
    values (v_ci, 1, r->>'s', null, md5(r->>'k'), 'draft', 'tutor_review_pending', r->>'a') returning id into v_civ;
    for c in select * from jsonb_array_elements(r->'c') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>0, c->>1, (c->>2)::boolean, c->>3);
    end loop;
  end loop;
  select count(*) into n from app.content_items ci join app.content_item_versions v on v.content_item_id=ci.id join app.mcq_choices m on m.content_item_version_id=v.id
   where ci.exam_pack_version_id='2d88ba5e-a6a3-43b8-bfae-9e5505a178a7' and ci.status='draft' and ci.content_key in (select x->>'k' from jsonb_array_elements(p) x);
  if n <> 40 then raise exception 'chunk 7: expected 40 choice rows, got %', n; end if;
  raise notice 'chunk 7: loaded 10 draft items';
end
$do$;
